material_type": "Remorque", "description": "PATTE D''OIE TEXTILE DIAM=46mm L=15M", "swl_tonnes": null, "checks": {"EG": "ok", "NID": "pending", "V1": "ok", "V2": "ok", "V3": "ok", "V4": "ok", "V5": "ok"}, "condition": "repair", "observations": "Maintien en Service après Réparation - Fit for use after repair"}]'::jsonb) loop
    insert into public.lifting_inventory(company_id,vessel_id,kind,reference,material_type,description,swl_tonnes,notes,source_label)
    values(v.company_id,v.id,source_row->>'kind',source_row->>'reference',source_row->>'material_type',source_row->>'description',
      (source_row->>'swl_tonnes')::numeric,coalesce(source_row->>'observations',''),
      case source_row->>'kind' when 'towing' then 'SUR - Registre des remorques - 2026.pdf' else 'SUR - Registre des apparaux de levage - 2026.pdf' end)
    on conflict(company_id,vessel_id,reference) do nothing;
  end loop;
  foreach source_kind in array array['lifting','towing'] loop
    issued := case source_kind when 'lifting' then date '2026-01-22' else date '2025-11-26' end;
    expiry := (issued+interval '1 year')::date;
    select * into cert from public.fleet_certificates where company_id=v.company_id and vessel_id=v.id
      and file_name=case source_kind when 'lifting' then 'SUR - Registre des apparaux de levage - 2026.pdf' else 'SUR - Registre des remorques - 2026.pdf' end
      and storage_path is not null order by id limit 1;
    if cert.id is not null then
      update public.fleet_certificates set issued_on=issued,expires_on=expiry,alarm_on=expiry-90,
        category_key=case source_kind when 'towing' then '08-5-remorques' else '08-3-accessoires-levage' end,
        category_label=case source_kind when 'towing' then '08.5 - Remorques' else '08.3 - Accessoires de levage' end
        where id=cert.id;
